from pybricks.parameters import Stop

from Team_Phoenix_Library import phoenix_gyro_spin_turn_the_old_way

def run_orange_mission(drive_base2, left_drive, right_drive, left_attachment, right_attachment):
    drive_base2.drive(1000, 1000)
    drive_base2.straight(75)
    print('a')
    drive_base2.settings(turn_rate=50)
    phoenix_gyro_spin_turn_the_old_way(100, -87, 40, -87, 'left', drive_base2, left_drive, right_drive)
    drive_base2.straight(175)
    right_attachment.run_angle(100, -250)
    drive_base2.straight(-25)
    right_attachment.run_angle(50, 140)
    right_attachment.run_angle(50, -10)
    drive_base2.straight(-20)
    right_attachment.run_angle(250, -250)
    drive_base2.straight(20)
    right_attachment.run_angle(500, 250)
    right_drive.straight(-250)


